public class RemittanceBatchEngine {
    private double totalDisbursed = 0.0;
    private double totalFees = 0.0;

    public void processBatch(double[] amounts) {
        for (int i = 0; i <= amounts.length; i++) {
            double amt = amounts[i]
            if (amt <= 0) {
                continue;
            }
            double fee = amt * 0.02;
            totalDisbursed += amt;
            totalFees = fee;
        }
    }
}
